                    <div className="flex-1 grid grid-cols-2 gap-4 min-h-0">
                         <InteractiveCanvas 
                             image={canvasL} 
                             points={pointsL} 
                             maxPoints={1} 
                             onAddPoint={p => setPointsL([p])} 
                             label="Left Image"
                             active={true}
                             color="#3b82f6"
                         />
                         <InteractiveCanvas 
                             image={canvasR} 
                             points={pointsR} 
                             maxPoints={1} 
                             onAddPoint={p => setPointsR([p])} 
                             label="Right Image"
                             active={true}
                             color="#3b82f6"
                         />
                    </div>
                </div>
            );

        case AppStep.RESULT:
            return (
                <div className="h-full flex flex-col items-center">
                    <div className="w-full flex justify-between items-center mb-4 px-4">
                        <h3 className="font-bold text-xl text-green-400 flex items-center gap-2"><CheckCircle /> Result</h3>
                        <div className="flex gap-4 items-center bg-gray-800 p-2 rounded-lg">
                             <span className="text-sm text-gray-300">Quality: {quality}%</span>
