                        ) : (
                            <p>Processing error.</p>
                        )}
                    </div>
                    <div className="mt-4">
                        <button onClick={resetAll} className="px-4 py-2 text-gray-400 hover:text-white flex items-center gap-2">
                            <RotateCcw size={16}/> Start Over
