                <div className="flex gap-2">
                   {step !== AppStep.UPLOAD && (
                       <button onClick={resetAll} className="text-sm text-red-400 hover:text-red-300 px-3 py-1 border border-red-900/50 bg-red-900/20 rounded">
                          Reset
